def main():
    files = sorted(f for f in glob.glob(os.path.join(BP, 'Part-*.md')) if not os.path.basename(f).startswith('Part-11-23'))
    occ = []; summ = []
    comp = [(e, re.compile(e[2], re.I), re.compile(e[3], re.I)) for e in E]
    for f in files:
        lab = part_label(f)
        for n, l in enumerate(open(f, encoding='utf-8'), 1):
            if l.startswith('> **Erratum v1.2'):   # v1.2 erratum markers (Part 11.25) are pointers, not content
                continue
            for e, sp, ap in comp:
                if sp.search(l):
                    st = 'annotated' if ap.search(l) else 'stale'
                    occ.append(dict(erratum=e[0], part=lab, line=n, state=st, text=l.strip()[:200]))
    for e, _, _ in comp:
        o = [x for x in occ if x['erratum'] == e[0]]
        stale = [x for x in o if x['state'] == 'stale']
        parts = []
        for x in stale:
            p = 'Part %s L%d' % (x['part'], x['line'])
            if len(parts) < 6:
                parts.append(p)
        summ.append(dict(id=e[0], title=e[1], current=e[4], authority=e[5], reported_by=e[6], occurrences=len(o), stale=len(stale), where=parts,
                         parts=sorted({x['part'] for x in stale})))
    with open(os.path.join(OUT, 'errata_occurrences.csv'), 'w', newline='', encoding='utf-8') as fh:
        w = csv.DictWriter(fh, fieldnames=['erratum', 'part', 'line', 'state', 'text']); w.writeheader(); w.writerows(occ)
    json.dump(summ, open(os.path.join(OUT, 'errata_summary.json'), 'w'), indent=1)
    for s in summ:
        print(s['id'], s['occurrences'], s['stale'], s['parts'][:8])
    print('total stale occurrences', sum(s['stale'] for s in summ))

if __name__ == '__main__':
    main()
